    struct CommitPause {
        after_successes: usize,
        reached: (Mutex<bool>, std::sync::Condvar),
        release: (Mutex<bool>, std::sync::Condvar),
    }

    impl CommitPause {
        fn new(after_successes: usize) -> Self {
            Self {
                after_successes,
                reached: (Mutex::new(false), std::sync::Condvar::new()),
                release: (Mutex::new(false), std::sync::Condvar::new()),
            }
        }

        fn wait_until_reached(&self) {
            let (lock, cv) = &self.reached;
            let mut reached = lock.lock().unwrap();
            while !*reached {
                reached = cv.wait(reached).unwrap();
            }
        }

        fn release(&self) {
            let (lock, cv) = &self.release;
            *lock.lock().unwrap() = true;
            cv.notify_all();
        }

        fn was_reached(&self) -> bool {
            *self.reached.0.lock().unwrap()
        }

        fn block(&self) {
            let (reached_lock, reached_cv) = &self.reached;
            *reached_lock.lock().unwrap() = true;
            reached_cv.notify_all();

            let (release_lock, release_cv) = &self.release;
            let mut released = release_lock.lock().unwrap();
            while !*released {
                released = release_cv.wait(released).unwrap();
            }
        }
    }

    struct RenewPause {
        reached: (Mutex<bool>, std::sync::Condvar),
        release: (Mutex<bool>, std::sync::Condvar),
    }

    impl RenewPause {
        fn new() -> Self {
            Self {
                reached: (Mutex::new(false), std::sync::Condvar::new()),
                release: (Mutex::new(false), std::sync::Condvar::new()),
            }
        }

        fn block(&self) {
            let (reached_lock, reached_cv) = &self.reached;
            *reached_lock.lock().unwrap() = true;
            reached_cv.notify_all();
            let (release_lock, release_cv) = &self.release;
            let mut release = release_lock.lock().unwrap();
            while !*release {
                release = release_cv.wait(release).unwrap();
            }
        }

        fn release(&self) {
            let (lock, cv) = &self.release;
            *lock.lock().unwrap() = true;
            cv.notify_all();
        }

        fn was_reached(&self) -> bool {
            *self.reached.0.lock().unwrap()
        }
    }

    #[cfg(feature = "dfs")]
    struct CountingMetaLog {
        inner: Arc<dyn crate::meta::store::MetaLog>,
        commits: AtomicU64,
    }

    #[cfg(feature = "dfs")]
    impl CountingMetaLog {
        fn new(inner: Arc<dyn crate::meta::store::MetaLog>) -> Self {
            Self {
                inner,
                commits: AtomicU64::new(0),
            }
        }

        fn commit_count(&self) -> u64 {
            self.commits.load(Ordering::SeqCst)
        }
    }

    #[cfg(feature = "dfs")]
    impl crate::meta::store::MetaLog for CountingMetaLog {
        fn health(&self) -> crate::meta::store::MetaFuture<'_, ()> {
            self.inner.health()
        }
        fn persistence(&self) -> crate::meta::store::BackendPersistence {
            self.inner.persistence()
        }
        fn limits(&self) -> crate::meta::store::journal::LogLimits {
            self.inner.limits()
        }
        fn recover(
            &self,
        ) -> crate::meta::store::MetaFuture<'_, crate::meta::store::journal::RecoveredLog> {
            self.inner.recover()
        }
        fn append_and_sync(
            &self,
            expected: crate::meta::store::journal::LogTip,
            records: Vec<crate::meta::store::log::Record>,
        ) -> crate::meta::store::MetaFuture<'_, crate::meta::store::journal::LogTip> {
            Box::pin(async move {
                let tip = self.inner.append_and_sync(expected, records).await?;
                self.commits.fetch_add(1, Ordering::SeqCst);
                Ok(tip)
            })
        }
    }

